<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LUMIFLOWON — Profile Payout Wallet</title>@include('partials.lumiflowon-financial-theme')</head><body>@include('partials.lumiflowon-financial-nav')<main style="max-width:850px;margin:auto;padding:24px"><h1>Update Profile Wallet Address</h1><p>Enter your own BEP20 / TRC20 address and verify ownership with MetaMask / TronLink. Signing this message does not transfer funds. Never enter a private key.</p><label>Network<select id="wallet-network"><option>BEP20</option><option>TRC20</option></select></label><label>Your receiving address<input id="wallet-address" maxlength="64" placeholder="0x… or T…"></label><button id="connect-wallet" type="button">Verify & save profile address</button><p id="wallet-status" role="status"></p><h2>Saved verified wallets</h2><div id="wallets"></div><p><a href="{{ route('member.profile') }}">Back to Profile</a></p></main><script>
(()=>{const status=document.getElementById('wallet-status'),button=document.getElementById('connect-wallet');const api=async(path,data)=>{const r=await fetch(path,{method:data?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':{{ Illuminate\Support\Js::from(csrf_token()) }}},body:data?JSON.stringify(data):undefined});const d=await r.json();if(!r.ok)throw Error(d.message||'Wallet update failed.');return d;};const refresh=async()=>{const d=await api('/member/usdt-wallets');document.getElementById('wallets').replaceChildren();for(const w of d.wallets){const p=document.createElement('p');p.style.overflowWrap='anywhere';p.textContent=w.network+': '+w.address;document.getElementById('wallets').append(p);}};
button.onclick=async()=>{button.disabled=true;try{const network=document.getElementById('wallet-network').value;let address=document.getElementById('wallet-address').value.trim(),signature,challenge;if(network==='BEP20'){if(!window.ethereum?.request)throw Error('Open this page in MetaMask browser or install MetaMask.');const accounts=await window.ethereum.request({method:'eth_requestAccounts'});address=address||accounts[0];if(!accounts.some(a=>a.toLowerCase()===address.toLowerCase()))throw Error('Connect the account matching the address you entered.');challenge=await api('/member/usdt-wallets/challenge',{network,address});signature=await window.ethereum.request({method:'personal_sign',params:[challenge.message,address]});}else{if(window.tronLink?.request)await window.tronLink.request({method:'tron_requestAccounts'});const tron=window.tronWeb;if(!tron?.defaultAddress?.base58)throw Error('Open this page in TronLink browser or connect TronLink.');address=address||tron.defaultAddress.base58;if(address!==tron.defaultAddress.base58)throw Error('Connect the TronLink account matching your address.');challenge=await api('/member/usdt-wallets/challenge',{network,address});signature=await tron.trx.signMessageV2(challenge.message);}await api('/member/usdt-wallets/verify',{challenge_id:challenge.challenge_id,message:challenge.message,signature});document.getElementById('wallet-address').value=address;status.textContent='Profile wallet verified and saved successfully. प्रोफाइल address सेव हो गया है।';status.style.color='#86efac';await refresh();}catch(e){status.textContent=e.message;status.style.color='#fda4af';}finally{button.disabled=false;}};refresh().catch(e=>status.textContent=e.message);
})();</script></body></html>
